$lines=Get-Content .env.local; foreach($line in $lines){if($line -match '^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)\s*$'){ $n=$matches[1];$v=$matches[2].Trim().Trim('"').Trim("'");if($n -eq 'SUPABASE_URL' -or $n -eq 'SUPABASE_SERVICE_ROLE_KEY'){Set-Item "Env:$n" $v}}}
$h=@{apikey=$env:SUPABASE_SERVICE_ROLE_KEY;Authorization="Bearer $env:SUPABASE_SERVICE_ROLE_KEY";'Content-Type'='application/json';Prefer='return=representation'};$b="$env:SUPABASE_URL/rest/v1";$fid='55c69451-adec-4503-8cf3-f134d9783142'
function Api($method,$uri,$body=$null){if($null -eq $body){return Invoke-RestMethod $uri -Headers $h -Method $method -TimeoutSec 45};return Invoke-RestMethod $uri -Headers $h -Method $method -Body ($body|ConvertTo-Json -Depth 6 -Compress) -TimeoutSec 45}
