$rooms=@(@{id='f4223b3d-a632-4ddf-bf93-c4eb6b499cb2';number='108';capacity=3},@{id='fb4cd3c2-2980-45c2-83ed-d3a3fd4c0a4f';number='110';capacity=3},@{id='c1485eca-28c9-4b0d-8a28-e4228a78aba1';number='202';capacity=4},@{id='7f8136f7-fc7a-4098-b472-53b22ec7004b';number='204';capacity=4},@{id='f79dabfa-6e46-4a11-8446-235a0b1755ec';number='206';capacity=3})
$createdMembers=@();$createdAllocations=@();$roomIndex=0;$roomUsed=0
try { foreach($g in $guests){while($roomIndex -lt $rooms.Count -and $roomUsed -ge $rooms[$roomIndex].capacity){$roomIndex++;$roomUsed=0};if($roomIndex -ge $rooms.Count){throw 'Pothi 56 Atithi capacity exhausted.'};$room=$rooms[$roomIndex];$m=Api Post "$b/members" @{family_id=$fid;name=$g[0];age=[int]$g[1];gender=$g[2];mobile=$g[3];is_head=$false}|Select-Object -First 1;$createdMembers+=$m;$a=Api Post "$b/room_allocations" @{room_id=$room.id;member_id=$m.id;family_id=$fid}|Select-Object -First 1;$createdAllocations+=$a;$roomUsed++};Write-Output "Pothi 56: added $($guests.Count) guests and allotted them in Atithi Hotel."}catch{foreach($a in $createdAllocations){Api Delete "$b/room_allocations?id=eq.$($a.id)"|Out-Null};foreach($m in $createdMembers){Api Delete "$b/members?id=eq.$($m.id)"|Out-Null};throw}
